import{_ as t,l,o as e,c as o,v as i,p as n,x as p,d as s,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"间接效用与支出函数","description":"","frontmatter":{"title":"间接效用与支出函数","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/indirect-utility.md","filePath":"econ/indirect-utility.md","lastUpdated":1789023840000}'),d={name:"econ/indirect-utility.md"};function u(h,a,A,_,B,m){const r=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=i('<h1 id="间接效用与支出函数" tabindex="-1">间接效用与支出函数 <a class="header-anchor" href="#间接效用与支出函数" aria-label="Permalink to &quot;间接效用与支出函数&quot;">​</a></h1><div class="epigraph"><p>支出函数是达到给定效用的最小开销；间接效用是给定价格与财富时能达到的最大效用。二者互为逆。</p><footer>—— 据 Varian, Microeconomic Analysis；Mas-Colell, Whinston and Green, Microeconomic Theory 第 3 章整理</footer></div><p><a href="/econ/interior-corner">上一课</a>（内点与角点）。给出了 \\(x(p,w)\\) 以及齐次性、瓦尔拉斯定律。本课不重讲预算几何，也不再推导一阶条件。缺口是：后课要把价格效应拆成「沿无差异面滑动」和「换到另一条无差异面」，必须先有一条以效用为约束的对偶问题，以及一个把 \\((p,w)\\) 映成已达效用的值函数。马歇尔需求本身不携带这两套函数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(x(p,w)\\) 回答「在这笔预算上选什么」。政策与福利常问另一句：价格变了，要多少钱才能回到原来的满足？或者：名义财富变了，满足变多少？这两个问题不能靠把 \\(x\\) 再写一遍来回答，因为 \\(x\\) 的坐标是商品，不是效用，也不是钱。缺口是引进两个值函数。</p><p>间接效用 \\(v(p,w)=u\\bigl(x(p,w)\\bigr)\\)，即最优值。支出函数</p> \\[e(p,u)=\\min_x\\bigl\\{p\\cdot x:u(x)\\ge u\\bigr\\}, \\]<p>即达到效用 \\(u\\) 的最便宜账单。希克斯需求 \\(h(p,u)\\) 是这个最小问题的解。本课的任务是钉死 \\(v\\) 与 \\(e\\) 互逆、以及它们对价格的导数如何回到需求——罗伊恒等式与谢泼德引理。斯勒茨基分解下一课才写。</p><h3 id="对偶不是另一套偏好" tabindex="-1">对偶不是另一套偏好 <a class="header-anchor" href="#对偶不是另一套偏好" aria-label="Permalink to &quot;对偶不是另一套偏好&quot;">​</a></h3><p>支出最小化用的仍是同一 \\(u\\)，同一 \\(\\succsim\\)。改的是约束：从「钱给定、效用最大」换成「效用给定、钱最小」。局部非餍足下，最优处 \\(u\\bigl(h(p,u)\\bigr)=u\\)，且 \\(e\\bigl(p,v(p,w)\\bigr)=w\\)。对偶缺口一旦补上，马歇尔与希克斯只是同一偏好的两种参数化。</p><p><span class="marginnote">\\(v\\) 随 \\(u\\) 的单调变换而变，\\(e\\) 的「效用刻度」也随之改。希克斯需求本身仍是序数对象：它只依赖于无差异集，不依赖于刻度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(v\\) 对 \\(p\\) 拟凸、对 \\(w\\) 递增，且 \\((p,w)\\) 零次齐次——因为 \\(x\\) 零次齐次，\\(u(x)\\) 只依赖比值。\\(e\\) 对 \\(p\\) 凹、一次齐次、对 \\(u\\) 递增。凹性来自：两个价格的平均去买，不会比分别买更贵。这些形状后课用来证明斯勒茨基矩阵负半定。</p><p>包络定理给出导数，不必把最优束对价格再全微分。谢泼德引理：\\(\\nabla_p e(p,u)=h(p,u)\\)。罗伊恒等式：</p> \\[x_i(p,w)=-\\frac{\\partial v/\\partial p_i}{\\partial v/\\partial w}. \\]<p>直观是：涨价的效用损失，除以财富的边际效用，等于必须减掉的消费。本课把这两条当对偶的可操作接口，不把包络证明重写一遍。</p>',16)),(e(),n(c,null,{default:p(()=>[E(r,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E9%A9%AC%E6%AD%87%E5%B0%94%E9%9C%80%E6%B1%82%20x(p%2Cw)%22%5D%20--%3E%20V%5B%22%E9%97%B4%E6%8E%A5%E6%95%88%E7%94%A8%20v(p%2Cw)%22%5D%0A%20%20U%5B%22%E6%95%88%E7%94%A8%E7%BA%A6%E6%9D%9F%20u%22%5D%20--%3E%20E%5B%22%E6%94%AF%E5%87%BA%E5%87%BD%E6%95%B0%20e(p%2Cu)%22%5D%0A%20%20E%20--%3E%20H%5B%22%E5%B8%8C%E5%85%8B%E6%96%AF%E9%9C%80%E6%B1%82%20h(p%2Cu)%22%5D%0A%20%20V%20--%3E%20ROY%5B%22%E7%BD%97%E4%BC%8A%E6%81%92%E7%AD%89%E5%BC%8F%22%5D%0A%20%20H%20--%3E%20SHEP%5B%22%E8%B0%A2%E6%B3%BC%E5%BE%B7%E5%BC%95%E7%90%86%22%5D%0A%20%20ROY%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%96%AF%E5%8B%92%E8%8C%A8%E5%9F%BA%E5%88%86%E8%A7%A3%22%5D%0A%20%20SHEP%20--%3E%20LATER%0A"})]),fallback:p(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>恒等式 \\(x(p,w)=h\\bigl(p,v(p,w)\\bigr)\\) 与 \\(h(p,u)=x\\bigl(p,e(p,u)\\bigr)\\) 把两条需求焊在一起。下一课对 \\(p\\) 求导，交叉项就是收入效应。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>值函数比原始需求更光滑、更好认。\\(e\\) 对 \\(p\\) 凹，立刻推出希克斯需求向下倾斜：自价格替代效应非正。马歇尔需求没有这层保护，因为收入效应可以翻号。这就是为什么补偿变化、等价变化用 \\(e\\) 来写，而不用 \\(x\\) 的积分乱加。</p><p>福利比较在本课只开一个口：价格从 \\(p^0\\) 变到 \\(p^1\\)，补偿变化是 \\(e(p^1,u^0)-e(p^0,u^0)\\)。这是钱，可以加总到一个人的两次预算上，仍然不是人际效用。后课税收归宿会再借这个口，本课不展开公共财政。</p><p><span class="marginnote">拟线性效用使 \\(e\\) 在计价物与效用之间仿射，收入效应集中在计价物上。这是后课局部均衡常用的刀，不是一般形状。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(v\\) 与 \\(e\\) 要求最优存在。价格为零或偏好在边界上不满足局部非餍足时，最小值可以是 \\(0\\) 或达不到。角点上谢泼德引理改成超梯度：支出函数仍凹，导数是对应。可微公式只在内点正则处使用。</p><p>也不要把间接效用当成「可观测的幸福指数」。观测到的是 \\((p,w,x)\\)；\\(v\\) 是模型里的值。显示偏好课会问：这些观测是否与某一 \\(u\\) 一致。本课仍走「偏好 → 对偶函数」方向。</p><p>补偿变化与等价变化用 \\(e\\) 定义，路径无关靠的是下一课才写清的 \\(S\\) 对称。本课只把值函数准备好，不把福利积分提前做完。价格指数后课会再借 \\(e\\)，对象是宏观核算，不是这里的消费者对偶。</p><p>后课默认：可以自由使用 \\(v\\)、\\(e\\)、\\(h\\)，以及罗伊、谢泼德两条导数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>间接效用是马歇尔问题的值；支出函数是效用约束下的最小账单。</li><li>二者互逆；\\(x\\) 与 \\(h\\) 只是同一偏好的两种参数化。</li><li>谢泼德引理与罗伊恒等式用包络把需求从值函数读出。</li><li>希克斯自价格效应非正；马歇尔效应的符号留给斯勒茨基。</li><li>出处：Varian, <em>Microeconomic Analysis</em>；Mas-Colell, Whinston and Green 第 3 章。</li></ul>',12))])}const f=t(d,[["render",u]]);export{b as __pageData,f as default};
